SELECT MIN(GSserved) AS lowest_grade_served
FROM schools
WHERE NCESDist = '0632640' AND GSserved IS NOT NULL;

baseline.sql:
SELECT COUNT(DISTINCT name) AS card_count
FROM cards
WHERE text IS NOT NULL AND TRIM(text) != ''
  AND (
    frameVersion = '2015'
    OR (
      frameVersion IS NOT NULL AND frameVersion != '' AND frameVersion >= '2016'
    )
  );

SELECT COUNT(DISTINCT language) AS num_languages
FROM foreign_data
WHERE name = 'Swamp';

treatment.sql:
SELECT ROUND(100.0 * COUNT(CASE WHEN m.member_id IS NULL THEN 1 END) / COUNT(DISTINCT mj.major_id), 2) AS pct_majors_with_no_members
FROM major mj
LEFT JOIN member m ON mj.major_id = m.link_to_major;

SELECT MAX(CAST(RNP AS FLOAT)) AS highest_rnp_value
FROM Laboratory
WHERE RNP IS NOT NULL;

SELECT ROUND(
  100.0 * SUM(CASE WHEN Diagnosis = 'SLE' THEN 1 ELSE 0 END) / COUNT(*), 2
) AS sle_percentage_among_thrombosis_patients
FROM Examination
WHERE Thrombosis = 1;

SELECT MAX(CAST(RNP AS FLOAT)) AS max_rnp
FROM Laboratory
WHERE CRE < 1.5 AND RNP IS NOT NULL;

